package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootStatusRecoveryScopeTest {
 @Test public void exactlyThreeIndependentReadSlots(){assertTrue(RootStatusRecoveryScope.ACTIVE);assertEquals(3,RootStatusRecoveryScope.MAX_FRAMES);assertEquals(15,RootStatusRecoveryScope.SOURCE_TASK_ID);Set<String> slots=new HashSet<>();for(int i=1;i<=3;i++)assertTrue(slots.add(RootStatusRecoveryScope.slot(i)));assertEquals(Set.of("READ_1","READ_2","READ_3"),slots);for(int i:new int[]{-1,0,4,Integer.MAX_VALUE})assertThrows(SecurityException.class,()->RootStatusRecoveryScope.slot(i));}
 @Test public void original180sAdmission(){long s=RootStatusRecoveryScope.STARTS_UTC,e=RootStatusRecoveryScope.EXPIRES_UTC;assertFalse(RootStatusRecoveryScope.current(s-1));assertTrue(RootStatusRecoveryScope.current(s));assertFalse(RootStatusRecoveryScope.current(e));assertTrue(RootStatusRecoveryScope.admissionCurrent(e-180001));assertFalse(RootStatusRecoveryScope.admissionCurrent(e-180000));assertEquals(181000,RootStatusRecoveryScope.sessionDeadline(1000,s));}
 @Test public void readDeadlineCannotExtendParentOrWindow(){long u=RootStatusRecoveryScope.STARTS_UTC;assertEquals(91000,RootStatusRecoveryScope.deadline(1000,u,181000));assertEquals(1500,RootStatusRecoveryScope.deadline(1000,u,1500));assertEquals(1001,RootStatusRecoveryScope.deadline(1000,RootStatusRecoveryScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidTimesFailClosed(){long u=RootStatusRecoveryScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootStatusRecoveryScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void namespaceNeverReusesPriorRuns(){assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootReturnReadScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootCurrentCardScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertThrows(SecurityException.class,()->RootStatusRecoveryScope.store(null,1));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.burnReturn(null,"safe"));}
 @Test public void invalidMetadataBeforeAnyWrite()throws Exception{var st=RootStatusRecoveryScope.store(Path.of("unused"),1);assertThrows(SecurityException.class,()->st.burn("invalid","safe"));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootStatusRecoveryScope.burnReturn(Path.of("unused"),null));}
 @Test public void durableFixedReturnNoTapOrRecoveryPrimitive()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootStatusRecoveryScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootStatusRecoveryScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertTrue(s.contains("burn(files,\"RETURN\""));assertFalse(s.contains("burnAction"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=3 maxTap=0 maxReturn=1"));}
}
